    step("SERVER_NAME 带端口('example.test:8000')时,Host 头也要带同样的端口:example.test:8000 → 主域,api.example.test:8000 → api 子域;api.example.test(无端口)与 api.example.test:9999 都是 404。", t=tl(S(4)), done=lidx(S(4), '3b'), mark=lidx(S(4), 'Host api.example.test  ', 'Host api.example.test:9999'), kv=KV([['Host 带对端口', '匹配'], ['端口不对或缺失', '404']], ['端口不对或缺失'])),
    step("url_for 对子域名路由:SERVER_NAME='example.test:5000' 时 url_for('api_index') → http://api.example.test:5000/;url_for('user_index', user='ann') → http://ann.example.test:5000/;url_for('www_index') 在主域里是相对 /,_external=True 是 http://example.test:5000/。", t=tl(S(5)), done=lidx(S(5), 'url_for("api_index")'), kv=KV([['api_index', 'http://api.example.test:5000/'], ['user_index(user=ann)', 'http://ann.example.test:5000/']], ['api_index'])),
    step("真实 HTTP(gunicorn,用 Host 头模拟):Host: example.test:端口 → www 首页;api.example.test:端口 → api 首页;ann.example.test:端口 → 用户 ann;不带端口的 example.test 与 evil.test:端口 → 都是 200「用户 <invalid>」。也就是说 Host 头伪造就能进入 <user> 路由,如果 <user> 路由对应敏感功能,必须自己校验。", t=tl(S(6)), done=lidx(S(6), 'Host: example.test:'), mark=lidx(S(6), 'Host: example.test  ', 'Host: evil.test'), kv=KV([['api.example.test:端口', 'api 首页'], ['example.test(无端口)', '用户 <invalid>'], ['evil.test:端口', '用户 <invalid>']], ['evil.test:端口'])),
    step("session cookie 与子域名:默认的 Set-Cookie 不带 Domain(只对设置它的主机生效);SESSION_COOKIE_DOMAIN='.example.test' 后 Set-Cookie 里是 Domain=example.test(开头的点被去掉,作用于该域名及其子域名),这样 api 与 www 可以共享登录状态。", t=tl(S(7)), done=lidx(S(7), '默认:'), mark=lidx(S(7), 'SESSION_COOKIE_DOMAIN'), kv=KV([['默认', '无 Domain,只对当前主机'], ['SESSION_COOKIE_DOMAIN', 'Domain=example.test']], ['SESSION_COOKIE_DOMAIN'])),
